import { useCallback, useRef, useState } from "react";
import { cancelSession, streamPrompt, type ThinkingLevel } from "../api/client";
import {
  startRuntimePrompt,
  type RuntimePromptHandle,
} from "../runtime/promptStream";
import type { RuntimeTransport } from "../runtime/runtimeTransport";
import {
  applyTurnEventToBlocks,
  blocksToContent,
  type TurnBlock,
  type TurnStatus,
} from "../utils/turnEvents";

export type { TurnBlock } from "../utils/turnEvents";

export interface ChatMessage {
  id: string;
  role: "user" | "assistant" | "error";
  content: string;
  blocks: TurnBlock[];
  streaming?: boolean;
  turnStatus?: TurnStatus;
  timestamp: number;
}

let messageIdCounter = 0;
function nextId(): string {
  return `msg-${Date.now()}-${++messageIdCounter}`;
}

export type RunState = "idle" | "running" | "stopping";

const CANCELLATION_ERROR_MESSAGE =
  "Could not stop the current response. Try again.";

export function useAgentStream(
  sessionId: string | undefined,
  runtimeTransport?: RuntimeTransport,
) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [runState, setRunState] = useState<RunState>("idle");
  const abortRef = useRef<AbortController | null>(null);
  const promptHandleRef = useRef<RuntimePromptHandle | null>(null);
  const promptStartRef = useRef<Promise<RuntimePromptHandle> | null>(null);
  const cancelInFlightRef = useRef(false);
  const queuedPromptRef = useRef<{
    prompt: string;
    model?: string;
    thinking?: ThinkingLevel;
  } | null>(null);

  const startPrompt = useCallback(
    async (prompt: string, model?: string, thinking?: ThinkingLevel) => {
      if (!sessionId) return;
      const normalizedPrompt = prompt.trim();
      if (!normalizedPrompt) return;

      setMessages((prev) => [
        ...prev,
        {
          id: nextId(),
          role: "user",
          content: normalizedPrompt,
          blocks: [],
          timestamp: Date.now(),
        },
      ]);

      setRunState("running");
      const controller = new AbortController();
      abortRef.current = controller;

      const turnId = nextId();
      const blocks: TurnBlock[] = [];
      let rafId: number | null = null;
      let turnStatus: TurnStatus = "completed";

      function upsertTurn(done = false) {
        const allText = blocksToContent(blocks);
        const snapshot = blocks.map((b) => ({ ...b }));

        setMessages((prev) => {
          const msg: ChatMessage = {
            id: turnId,
            role: "assistant",
            content: allText,
            blocks: snapshot,
            streaming: !done,
            turnStatus: done ? turnStatus : undefined,
            timestamp: Date.now(),
          };
          const idx = prev.findIndex((m) => m.id === turnId);
          if (idx >= 0) {
            const next = [...prev];
            next[idx] = msg;
            return next;
          }
          return [...prev, msg];
        });
      }

      function scheduleUpsert(done = false) {
        if (done) {
          if (rafId) cancelAnimationFrame(rafId);
          rafId = null;
          upsertTurn(true);
          return;
        }
        if (rafId) return;
        rafId = requestAnimationFrame(() => {
          rafId = null;
          upsertTurn(false);
        });
      }

      try {
        const promptStart = runtimeTransport
          ? startRuntimePrompt(runtimeTransport, sessionId, {
              prompt: normalizedPrompt,
              model,
              thinking,
              signal: controller.signal,
            })
          : null;
        promptStartRef.current = promptStart;
        const runtimePrompt = promptStart ? await promptStart : null;
        promptHandleRef.current = runtimePrompt;
        const eventSource = runtimePrompt
          ? runtimePrompt.events()
          : streamPrompt(
              sessionId,
              normalizedPrompt,
              model,
              thinking,
              controller.signal,
            );
        for await (const event of eventSource) {
          const applyResult = applyTurnEventToBlocks(blocks, event, nextId);
          if (applyResult.status) {
            turnStatus = applyResult.status;
            scheduleUpsert(true);
            if (applyResult.status !== "completed" || event.type === "result") {
              break;
            }
            continue;
          }
          if (applyResult.changed) {
            scheduleUpsert();
          }
        }
      } catch (e) {
        if (!(e instanceof DOMException && e.name === "AbortError")) {
          blocks.push({
            id: nextId(),
            type: "error",
            text: e instanceof Error ? e.message : "Stream failed",
          });
          turnStatus = "failed";
          scheduleUpsert(true);
        }
      } finally {
        if (rafId) cancelAnimationFrame(rafId);
        abortRef.current = null;
        promptHandleRef.current = null;
        promptStartRef.current = null;

        const queuedPrompt = queuedPromptRef.current;
        queuedPromptRef.current = null;
        setRunState("idle");

        // Always replay a queued steering prompt once the active run finishes.
        if (queuedPrompt) {
          void startPrompt(
            queuedPrompt.prompt,
            queuedPrompt.model,
            queuedPrompt.thinking,
          );
        }
      }
    },
    [runtimeTransport, sessionId],
  );

  const cancel = useCallback(async () => {
    if (runState !== "running" || cancelInFlightRef.current) return;
    cancelInFlightRef.current = true;
    const activeController = abortRef.current;
    setRunState("stopping");
    try {
      if (sessionId) {
        if (runtimeTransport) {
          const promptHandle =
            promptHandleRef.current ?? (await promptStartRef.current);
          if (promptHandle) {
            await promptHandle.cancel();
          }
        } else {
          await cancelSession(sessionId);
        }
      }
    } catch {
      if (
        activeController !== null &&
        abortRef.current === activeController
      ) {
        setRunState("running");
      }
      setMessages((prev) => [
        ...prev,
        {
          id: nextId(),
          role: "error",
          content: CANCELLATION_ERROR_MESSAGE,
          blocks: [],
          timestamp: Date.now(),
        },
      ]);
    } finally {
      cancelInFlightRef.current = false;
    }
  }, [runtimeTransport, sessionId, runState]);

  const sendPrompt = useCallback(
    async (prompt: string, model?: string, thinking?: ThinkingLevel) => {
      if (!sessionId) return;
      const normalizedPrompt = prompt.trim();
      if (!normalizedPrompt) return;

      if (runState === "running") {
        // Queue steering prompt and request stop
        queuedPromptRef.current = { prompt: normalizedPrompt, model, thinking };
        await cancel();
        return;
      }

      if (runState === "stopping") {
        // Replace queued steering prompt
        queuedPromptRef.current = { prompt: normalizedPrompt, model, thinking };
        return;
      }

      // runState === "idle", start normally
      await startPrompt(normalizedPrompt, model, thinking);
    },
    [cancel, runState, startPrompt],
  );

  return {
    messages,
    sendPrompt,
    cancel,
    runState,
    setMessages,
    streaming: runState === "running" || runState === "stopping",
  };
}

import type { SSEEvent } from "../api/client";

export type TurnStatus = "completed" | "cancelled" | "failed";

export interface TurnBlock {
  id: string;
  type: "text" | "thinking" | "tool_use" | "error" | "status";
  text?: string;
  severity?: "info" | "warning" | "error";
  toolName?: string;
  toolInput?: unknown;
  toolId?: string;
  toolOutput?: string;
  toolError?: boolean;
}

export interface TurnEventApplyResult {
  changed: boolean;
  status?: TurnStatus;
}

const STORED_TURN_SCHEMA = "yinshi.assistant_turn.v1";

function appendOrCreate(
  blocks: TurnBlock[],
  type: "text" | "thinking",
  text: string,
  createBlockId: () => string,
): boolean {
  if (!text) {
    return false;
  }
  const last = blocks[blocks.length - 1];
  if (last && last.type === type) {
    last.text = (last.text || "") + text;
  } else {
    blocks.push({ id: createBlockId(), type, text });
  }
  return true;
}

function stringifyOutput(content: unknown): string {
  if (typeof content === "string") {
    return content;
  }
  if (content === null || content === undefined) {
    return "";
  }
  return JSON.stringify(content, null, 2);
}

function parseToolInput(block: TurnBlock): void {
  if (block.type !== "tool_use") {
    return;
  }
  if (typeof block.toolInput !== "string") {
    return;
  }
  try {
    block.toolInput = JSON.parse(block.toolInput);
  } catch {
    // Partial tool-call JSON is still useful to show as raw text.
  }
}

function applyAssistantEvent(
  blocks: TurnBlock[],
  event: Extract<SSEEvent, { type: "assistant" }>,
  createBlockId: () => string,
): boolean {
  let changed = false;
  for (const block of event.message?.content ?? []) {
    if (block.type === "text") {
      changed = appendOrCreate(blocks, "text", block.text || "", createBlockId) || changed;
    } else if (block.type === "thinking") {
      changed = appendOrCreate(
        blocks,
        "thinking",
        block.thinking || block.text || "",
        createBlockId,
      ) || changed;
    } else if (block.type === "tool_use") {
      blocks.push({
        id: block.id || createBlockId(),
        type: "tool_use",
        toolName: block.name || "unknown",
        toolInput: block.input,
        toolId: block.id,
      });
      changed = true;
    }
  }
  return changed;
}

function applyContentBlockStart(
  blocks: TurnBlock[],
  event: Extract<SSEEvent, { type: "content_block_start" }>,
  createBlockId: () => string,
): boolean {
  const contentBlock = event.content_block;
  if (contentBlock.type === "tool_use") {
    blocks.push({
      id: contentBlock.id || createBlockId(),
      type: "tool_use",
      toolName: contentBlock.name || "unknown",
      toolInput: contentBlock.input,
      toolId: contentBlock.id,
    });
    return true;
  }
  if (contentBlock.type === "thinking") {
    blocks.push({
      id: createBlockId(),
      type: "thinking",
      text: contentBlock.thinking || "",
    });
    return true;
  }
  if (contentBlock.type === "text") {
    blocks.push({
      id: createBlockId(),
      type: "text",
      text: contentBlock.text || "",
    });
    return true;
  }
  return false;
}

function applyContentBlockDelta(
  blocks: TurnBlock[],
  event: Extract<SSEEvent, { type: "content_block_delta" }>,
  createBlockId: () => string,
): boolean {
  const delta = event.delta;
  if (delta.type === "text_delta") {
    return appendOrCreate(blocks, "text", delta.text || "", createBlockId);
  }
  if (delta.type === "thinking_delta") {
    return appendOrCreate(blocks, "thinking", delta.thinking || delta.text || "", createBlockId);
  }
  if (delta.type === "input_json_delta") {
    const last = blocks[blocks.length - 1];
    if (last && last.type === "tool_use") {
      const partial = delta.partial_json || "";
      last.toolInput = ((last.toolInput as string) || "") + partial;
      return true;
    }
  }
  return false;
}

function applyToolResult(
  blocks: TurnBlock[],
  event: Extract<SSEEvent, { type: "tool_result" }>,
): boolean {
  const matching = blocks.find(
    (block) => block.type === "tool_use" && block.toolId === event.tool_use_id,
  );
  if (!matching) {
    return false;
  }
  matching.toolOutput = stringifyOutput(event.content);
  matching.toolError = event.is_error;
  return true;
}

export function applyTurnEventToBlocks(
  blocks: TurnBlock[],
  event: SSEEvent,
  createBlockId: () => string,
): TurnEventApplyResult {
  switch (event.type) {
    case "assistant":
      return { changed: applyAssistantEvent(blocks, event, createBlockId) };
    case "tool_use":
      blocks.push({
        id: event.id || createBlockId(),
        type: "tool_use",
        toolName: event.name || event.tool_name || "unknown",
        toolInput: event.input,
        toolId: event.id,
      });
      return { changed: true };
    case "content_block_start":
      return { changed: applyContentBlockStart(blocks, event, createBlockId) };
    case "content_block_delta":
      return { changed: applyContentBlockDelta(blocks, event, createBlockId) };
    case "content_block_stop": {
      const last = blocks[blocks.length - 1];
      if (last) {
        parseToolInput(last);
      }
      return { changed: true };
    }
    case "tool_result":
      return { changed: applyToolResult(blocks, event) };
    case "result":
    case "message_stop":
      return { changed: false, status: "completed" };
    case "cancelled":
      return { changed: false, status: "cancelled" };
    case "status":
      blocks.push({
        id: createBlockId(),
        type: "status",
        text: event.message || event.status,
        severity: event.severity || "info",
      });
      return { changed: true };
    case "error":
      blocks.push({ id: createBlockId(), type: "error", text: event.error });
      return { changed: true, status: "failed" };
    case "message_start":
    case "message_delta":
      return { changed: false };
    default:
      return { changed: false };
  }
}

export function blocksToContent(blocks: TurnBlock[]): string {
  return blocks
    .filter((block) => block.type === "text")
    .map((block) => block.text || "")
    .join("");
}

function normalizeStoredEvent(rawEvent: unknown): SSEEvent | null {
  if (!rawEvent || typeof rawEvent !== "object") {
    return null;
  }
  const record = rawEvent as Record<string, unknown>;
  if (record.type === "message") {
    return normalizeStoredEvent(record.data);
  }
  if (record.type === "tool_use") {
    return {
      type: "tool_use",
      name: String(record.toolName || record.name || record.tool_name || "unknown"),
      id: typeof record.id === "string" ? record.id : undefined,
      input: record.toolInput ?? record.input,
    };
  }
  return record as SSEEvent;
}

function extractStoredEvents(fullMessage: string): SSEEvent[] {
  const parsed = JSON.parse(fullMessage) as unknown;
  if (!parsed || typeof parsed !== "object") {
    return [];
  }
  const record = parsed as Record<string, unknown>;
  if (record.schema === STORED_TURN_SCHEMA && Array.isArray(record.events)) {
    return record.events.flatMap((event) => {
      const normalizedEvent = normalizeStoredEvent(event);
      return normalizedEvent ? [normalizedEvent] : [];
    });
  }
  const normalizedEvent = normalizeStoredEvent(record);
  return normalizedEvent ? [normalizedEvent] : [];
}

export function parseStoredTurnBlocks(
  fullMessage: string | null | undefined,
  createBlockId: () => string,
): TurnBlock[] {
  if (!fullMessage) {
    return [];
  }

  let events: SSEEvent[];
  try {
    events = extractStoredEvents(fullMessage);
  } catch {
    return [];
  }

  const blocks: TurnBlock[] = [];
  for (const event of events) {
    applyTurnEventToBlocks(blocks, event, createBlockId);
  }
  return blocks;
}

import { describe, expect, it, vi } from "vitest";

import { RunnerRelayConnectionError } from "../runner/encryptedRunnerClient";
import type { RuntimeTransport } from "./runtimeTransport";
import { startRuntimePrompt } from "./promptStream";

const sessionId = "a".repeat(32);
const runId = "b".repeat(32);

function transport(): RuntimeTransport {
  return {
    runtime: { location: "hosted" },
    get: vi.fn(),
    post: vi.fn(),
    patch: vi.fn(),
    put: vi.fn(),
    delete: vi.fn(),
    upload: vi.fn(),
    close: vi.fn(),
  };
}

describe("runtime prompt stream", () => {
  it("reconnects from durable event sequence until terminal status", async () => {
    const runtimeTransport = transport();
    vi.mocked(runtimeTransport.post).mockResolvedValue({
      id: runId,
      session_id: sessionId,
      status: "starting",
    });
    vi.mocked(runtimeTransport.get)
      .mockResolvedValueOnce({
        run_id: runId,
        status: "running",
        events: [{ type: "status", status: "started" }],
        next_sequence: 1,
      })
      .mockResolvedValueOnce({
        run_id: runId,
        status: "completed",
        events: [{ type: "result" }],
        next_sequence: 2,
      });

    const handle = await startRuntimePrompt(runtimeTransport, sessionId, {
      prompt: "hello",
      idempotencyKey: "22222222-2222-4222-8222-222222222222",
      pollDelayMs: 0,
    });
    const events = [];
    for await (const event of handle.events()) {
      events.push(event);
    }

    expect(events.map((event) => event.type)).toEqual(["status", "result"]);
    expect(runtimeTransport.get).toHaveBeenNthCalledWith(
      1,
      `/api/sessions/${sessionId}/runs/${runId}/events/0`,
    );
    expect(runtimeTransport.get).toHaveBeenNthCalledWith(
      2,
      `/api/sessions/${sessionId}/runs/${runId}/events/1`,
    );
  });

  it("resumes from the durable sequence after a relay disconnect", async () => {
    vi.useFakeTimers();
    try {
      const runtimeTransport = transport();
      vi.mocked(runtimeTransport.post).mockResolvedValue({
        id: runId,
        session_id: sessionId,
        status: "starting",
      });
      vi.mocked(runtimeTransport.get)
        .mockResolvedValueOnce({
          run_id: runId,
          status: "running",
          events: [{ type: "status", status: "started" }],
          next_sequence: 1,
        })
        .mockRejectedValueOnce(
          new RunnerRelayConnectionError(
            "Runner relay closed before responding",
          ),
        )
        .mockResolvedValueOnce({
          run_id: runId,
          status: "completed",
          events: [{ type: "result" }],
          next_sequence: 2,
        });
      const handle = await startRuntimePrompt(runtimeTransport, sessionId, {
        prompt: "hello",
        idempotencyKey: "22222222-2222-4222-8222-222222222222",
        pollDelayMs: 0,
      });
      const events: string[] = [];
      const collect = (async () => {
        for await (const event of handle.events()) {
          events.push(event.type);
        }
      })();

      await vi.runAllTimersAsync();
      await collect;

      expect(events).toEqual(["status", "result"]);
      expect(runtimeTransport.get).toHaveBeenNthCalledWith(
        1,
        `/api/sessions/${sessionId}/runs/${runId}/events/0`,
      );
      expect(runtimeTransport.get).toHaveBeenNthCalledWith(
        2,
        `/api/sessions/${sessionId}/runs/${runId}/events/1`,
      );
      expect(runtimeTransport.get).toHaveBeenNthCalledWith(
        3,
        `/api/sessions/${sessionId}/runs/${runId}/events/1`,
      );
    } finally {
      vi.useRealTimers();
    }
  });

  it("uses the remote polling interval for a managed runtime", async () => {
    vi.useFakeTimers();
    try {
      const runtimeTransport: RuntimeTransport = {
        ...transport(),
        runtime: {
          location: "managed",
          runnerPublicKey: "REDACTED",
        },
      };
      vi.mocked(runtimeTransport.post).mockResolvedValue({
        id: runId,
        session_id: sessionId,
        status: "starting",
      });
      vi.mocked(runtimeTransport.get)
        .mockResolvedValueOnce({
          run_id: runId,
          status: "running",
          events: [],
          next_sequence: 0,
        })
        .mockResolvedValueOnce({
          run_id: runId,
          status: "completed",
          events: [{ type: "result" }],
          next_sequence: 1,
        });
      const handle = await startRuntimePrompt(runtimeTransport, sessionId, {
        prompt: "hello",
        idempotencyKey: "22222222-2222-4222-8222-222222222222",
      });

      const nextEvent = handle.events().next();
      await vi.advanceTimersByTimeAsync(749);
      expect(runtimeTransport.get).toHaveBeenCalledTimes(1);
      await vi.advanceTimersByTimeAsync(1);

      await expect(nextEvent).resolves.toMatchObject({
        done: false,
        value: { type: "result" },
      });
      expect(runtimeTransport.get).toHaveBeenCalledTimes(2);
    } finally {
      vi.useRealTimers();
    }
  });

  it("removes the abort listener after a poll delay resolves", async () => {
    vi.useFakeTimers();
    try {
      const runtimeTransport = transport();
      const controller = new AbortController();
      const addListener = vi.spyOn(controller.signal, "addEventListener");
      const removeListener = vi.spyOn(controller.signal, "removeEventListener");
      vi.mocked(runtimeTransport.post).mockResolvedValue({
        id: runId,
        session_id: sessionId,
        status: "starting",
      });
      vi.mocked(runtimeTransport.get)
        .mockResolvedValueOnce({
          run_id: runId,
          status: "running",
          events: [],
          next_sequence: 0,
        })
        .mockResolvedValueOnce({
          run_id: runId,
          status: "completed",
          events: [{ type: "result" }],
          next_sequence: 1,
        });
      const handle = await startRuntimePrompt(runtimeTransport, sessionId, {
        prompt: "hello",
        idempotencyKey: "22222222-2222-4222-8222-222222222222",
        pollDelayMs: 25,
        signal: controller.signal,
      });

      const nextEvent = handle.events().next();
      await vi.advanceTimersByTimeAsync(25);
      await expect(nextEvent).resolves.toMatchObject({
        done: false,
        value: { type: "result" },
      });
      const abortListener = addListener.mock.calls.find(
        ([eventName]) => eventName === "abort",
      )?.[1];

      expect(abortListener).toBeTypeOf("function");
      expect(removeListener).toHaveBeenCalledWith("abort", abortListener);
    } finally {
      vi.useRealTimers();
    }
  });

  it("clears a pending poll timer and rejects once when aborted", async () => {
    vi.useFakeTimers();
    try {
      const runtimeTransport = transport();
      const controller = new AbortController();
      const clearTimeout = vi.spyOn(window, "clearTimeout");
      vi.mocked(runtimeTransport.post).mockResolvedValue({
        id: runId,
        session_id: sessionId,
        status: "starting",
      });
      vi.mocked(runtimeTransport.get).mockResolvedValue({
        run_id: runId,
        status: "running",
        events: [],
        next_sequence: 0,
      });
      const handle = await startRuntimePrompt(runtimeTransport, sessionId, {
        prompt: "hello",
        idempotencyKey: "22222222-2222-4222-8222-222222222222",
        pollDelayMs: 25,
        signal: controller.signal,
      });

      const nextEvent = handle.events().next();
      await vi.advanceTimersByTimeAsync(0);
      expect(vi.getTimerCount()).toBe(1);
      const rejection = expect(nextEvent).rejects.toMatchObject({
        name: "AbortError",
      });

      controller.abort();
      controller.abort();

      await rejection;
      expect(clearTimeout).toHaveBeenCalledOnce();
      expect(runtimeTransport.get).toHaveBeenCalledOnce();
    } finally {
      vi.useRealTimers();
    }
  });

  it("surfaces the last relay error at the injected retry limit", async () => {
    vi.useFakeTimers();
    try {
      const runtimeTransport = transport();
      const firstError = new RunnerRelayConnectionError(
        "Runner relay closed before responding",
      );
      const lastError = new RunnerRelayConnectionError(
        "Runner relay response timed out",
      );
      vi.mocked(runtimeTransport.post).mockResolvedValue({
        id: runId,
        session_id: sessionId,
        status: "starting",
      });
      vi.mocked(runtimeTransport.get)
        .mockRejectedValueOnce(firstError)
        .mockRejectedValueOnce(lastError);
      const handle = await startRuntimePrompt(runtimeTransport, sessionId, {
        prompt: "hello",
        idempotencyKey: "22222222-2222-4222-8222-222222222222",
        pollDelayMs: 0,
        pollRetryLimit: 2,
      });

      const nextEvent = handle.events().next();
      const rejection = expect(nextEvent).rejects.toBe(lastError);
      await vi.runAllTimersAsync();

      await rejection;
